import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;

public class Main {
    public static void main(String[] args) throws Exception {
        Path 柜子 = Path.of("鱼塘", "深水区");
        Files.createDirectories(柜子);

        Path 门牌 = Path.of("鱼塘", "深水区", "账本.txt");

        Files.writeString(门牌, "{n1} {c1} 条\n");
        Files.writeString(门牌, "{n2} {c2} 条\n", StandardOpenOption.APPEND);

        System.out.println("几个字节：" + Files.size(门牌));
        System.out.print(Files.readString(门牌));
    }
}
